package main

import (
	"bufio"
	"fmt"
	"os"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal
	ScRate  decimal.Decimal
	ScYears int64
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string = ""

var curRec SchedRec
var schedLines []string
var schedIdx int
var schedFile *os.File

func isInputDone() bool { return WsEofFlag == "Y" }

func parseDigitsToScaled(s string, scale int32) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, -scale)
}

func parseRec(line string) SchedRec {
	if len(line) < 16 {
		for len(line) < 16 {
			line += " "
		}
	} else if len(line) > 16 {
		line = line[:16]
	}
	var r SchedRec
	r.ScAcct = line[0:4]
	r.ScPrin = parseDigitsToScaled(line[4:11], 2)
	r.ScRate = parseDigitsToScaled(line[11:15], 2)
	ys := line[15:16]
	var y int64 = 0
	if len(ys) > 0 {
		c := ys[0]
		if c >= '0' && c <= '9' {
			y = int64(c - '0')
		} else {
			y = 0
		}
	}
	r.ScYears = y
	return r
}

func storeWsBal(v decimal.Decimal) {
	scaled := v.Shift(2).Truncate(0)
	iv := scaled.IntPart()
	const mod int64 = 10000000000
	iv = iv % mod
	// COBOL unsigned truncation keeps low order; for negative keep sign of remainder
	WsBal = decimal.New(iv, -2)
}

func formatBalEd(v decimal.Decimal) string {
	// v has scale 2; get low-order 8 integer digits + 2 decimals
	scaled := v.Shift(2).Truncate(0).IntPart()
	if scaled < 0 {
		scaled = -scaled
	}
	const mod int64 = 10000000000
	scaled = scaled % mod
	if scaled < 0 {
		scaled += mod
	}
	intPart := scaled / 100
	fracPart := scaled % 100
	var d [8]int64
	tmp := intPart
	for i := 7; i >= 0; i-- {
		d[i] = tmp % 10
		tmp /= 10
	}
	f1 := fracPart / 10
	f2 := fracPart % 10
	// picture ZZ,ZZZ,ZZ9.99
	// map integer slots
	// positions: 0:Z(d0) 1:Z(d1) 2:, 3:Z(d2) 4:Z(d3) 5:Z(d4) 6:, 7:Z(d5) 8:Z(d6) 9:9(d7)
	out := make([]byte, 13)
	digits := []int64{d[0], d[1], d[2], d[3], d[4], d[5], d[6], d[7]}
	isZ := []bool{true, true, false, true, true, true, false, true, true, false}
	// We'll build sequentially tracking significance
	sig := false
	// First pass: determine significance: find first non-zero among digits
	// sig becomes true after printing a non-zero Z digit
	idxDigit := 0
	for pos := 0; pos <= 9; pos++ {
		if pos == 2 || pos == 6 {
			continue
		}
		_ = idxDigit
		idxDigit++
	}
	idxDigit = 0
	for pos := 0; pos <= 9; pos++ {
		if pos == 2 || pos == 6 {
			if sig {
				out[pos] = ','
			} else {
				// Look ahead: if any remaining integer digit non-zero, comma? In COBOL
				// commas in suppressed zone become spaces; our sequential rule gives space
				// unless significance already seen. But need to consider that a later
				// non-zero should not retroactively make earlier comma a comma.
				// Sequential is correct.
				out[pos] = ' '
			}
			continue
		}
		dig := digits[idxDigit]
		idxDigit++
		if isZ[pos] {
			if sig {
				out[pos] = byte('0' + dig)
			} else {
				if dig != 0 {
					out[pos] = byte('0' + dig)
					sig = true
				} else {
					// check if any later digit non-zero? suppression still space
					// if all remaining are zero, still space (until 9)
					out[pos] = ' '
				}
			}
		} else {
			// 9 position
			out[pos] = byte('0' + dig)
			// sig irrelevant
		}
	}
	out[10] = '.'
	out[11] = byte('0' + f1)
	out[12] = byte('0' + f2)
	return string(out)
}

func fmt99(n int64) string {
	m := n % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func READPARA() {
	if schedIdx < len(schedLines) {
		curRec = parseRec(schedLines[schedIdx])
		schedIdx++
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESSPARA() {
	// MOVE SC-PRIN TO WS-BAL (truncate to scale, overflow wrap)
	storeWsBal(curRec.ScPrin.Truncate(2))
	WsYear = 1
	for !(WsYear > curRec.ScYears) {
		factor := decimal.NewFromInt(1).Add(curRec.ScRate.Shift(-2))
		tmp := WsBal.Mul(factor)
		r := tmp.Round(2)
		storeWsBal(r)
		WsBalEd = formatBalEd(WsBal)
		fmt.Fprintln(os.Stdout, curRec.ScAcct+" Y"+fmt99(WsYear)+" "+WsBalEd)
		WsYear = WsYear + 1
	}
	WsBalEd = formatBalEd(WsBal)
	fmt.Fprintln(os.Stdout, curRec.ScAcct+" FINAL "+WsBalEd)
	WsCount = WsCount + 1
	// wrap PIC 99
	WsCount = WsCount % 100
	WsYear = WsYear % 100
	READPARA()
}

func MAINPARA() {
	f, err := os.Open("input.dat")
	if err != nil {
		// empty input -> treat as EOF
		schedLines = nil
	} else {
		schedFile = f
		sc := bufio.NewScanner(f)
		// allow long lines
		const maxCap = 1024 * 1024
		buf := make([]byte, 0, 64*1024)
		sc.Buffer(buf, maxCap)
		for sc.Scan() {
			line := sc.Text()
			schedLines = append(schedLines, line)
		}
		f.Close()
	}
	schedIdx = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	fmt.Fprintln(os.Stdout, "SCHEDULES: "+fmt99(WsCount))
}

func main() {
	MAINPARA()
}
